package main

import (
	"fmt"
	"os"
	"runtime"
	"time"
)

var (
	Version   = "dev"
	BuildTime = time.Date(2026, 4, 17, 19, 59, 35, 0, time.UTC).Format("Mon Jan 2 15:04:05 MST 2006")
	BuildUser = "root"
)

func main() {
	app := NewGdu()
	if err := app.Execute(); err != nil {
		fmt.Fprintf(os.Stderr, "Error: %v\n", err)
		os.Exit(1)
	}
}

type Gdu struct {
	// Version info
	Version   string
	BuildTime string
	BuildUser string

	// Flags
	NonInteractive bool
	NoProgress     bool
	Summarize      bool
	NoColor        bool
	ShowInKiB      bool
	SI             bool
	NoUnicode      bool
	ShowApparentSize bool
	ShowItemCount  bool
	ShowMTime      bool
	ShowRelativeSize bool
	ShowDisks      bool
	FollowSymlinks bool
	NoCross        bool
	NoHidden       bool
	NoPrefix       bool
	ReverseSort    bool
	Sequential     bool
	ArchiveBrowsing bool
	CollapsePath   bool
	NoDelete       bool
	NoSpawnShell   bool
	ReadFromStorage bool
	WriteConfig    bool
	EnableProfiling bool

	// Options with values
	Depth           int
	MaxCores        int
	Top             int
	ConfigFile      string
	DB              string
	InputFile       string
	OutputFile      string
	LogFile         string
	IgnoreDirs      []string
	IgnoreDirsPattern []string
	IgnoreFrom      string
	ExcludeType     []string
	Type            []string
	MaxAge          string
	MinAge          string
	Since           string
	Until           string
	Storage         string
	Style           string

	// Directory to scan
	ScanDir string
}

func NewGdu() *Gdu {
	return &Gdu{
		Version:   Version,
		BuildTime: BuildTime,
		BuildUser: BuildUser,
		MaxCores:  runtime.NumCPU(),
		LogFile:   "/dev/null",
	}
}

func (g *Gdu) Execute() error {
	args := os.Args[1:]

	// Parse flags and arguments
	if err := g.parseArgs(args); err != nil {
		return err
	}

	// Handle version flag
	if len(args) > 0 && (args[0] == "--version" || args[0] == "-v") {
		fmt.Printf("Version:\t %s\n", g.Version)
		fmt.Printf("Built time:\t %s\n", g.BuildTime)
		fmt.Printf("Built user:\t %s\n", g.BuildUser)
		return nil
	}

	// Handle help flag
	if len(args) == 0 || (len(args) > 0 && (args[0] == "--help" || args[0] == "-h")) {
		g.printHelp()
		return nil
	}

	// Run the scan
	if g.NonInteractive {
		return g.runNonInteractive()
	}

	return g.runInteractive()
}

func (g *Gdu) parseArgs(args []string) error {
	for i := 0; i < len(args); i++ {
		arg := args[i]

		switch arg {
		case "--version", "-v":
			// Handled separately
		case "--help", "-h":
			// Handled separately
		case "--non-interactive", "-n":
			g.NonInteractive = true
		case "--no-progress", "-p":
			g.NoProgress = true
		case "--summarize", "-s":
			g.Summarize = true
		case "--no-color", "-c":
			g.NoColor = true
		case "--show-in-kib", "-k":
			g.ShowInKiB = true
		case "--si":
			g.SI = true
		case "--no-unicode", "-u":
			g.NoUnicode = true
		case "--show-apparent-size", "-a":
			g.ShowApparentSize = true
		case "--show-item-count", "-C":
			g.ShowItemCount = true
		case "--show-mtime", "-M":
			g.ShowMTime = true
		case "--show-relative-size", "-B":
			g.ShowRelativeSize = true
		case "--show-disks", "-d":
			g.ShowDisks = true
		case "--follow-symlinks", "-L":
			g.FollowSymlinks = true
		case "--no-cross", "-x":
			g.NoCross = true
		case "--no-hidden", "-H":
			g.NoHidden = true
		case "--no-prefix":
			g.NoPrefix = true
		case "--reverse-sort":
			g.ReverseSort = true
		case "--sequential":
			g.Sequential = true
		case "--archive-browsing":
			g.ArchiveBrowsing = true
		case "--collapse-path":
			g.CollapsePath = true
		case "--no-delete":
			g.NoDelete = true
		case "--no-spawn-shell":
			g.NoSpawnShell = true
		case "--read-from-storage", "-r":
			g.ReadFromStorage = true
		case "--write-config":
			g.WriteConfig = true
		case "--enable-profiling":
			g.EnableProfiling = true

		// Flags with arguments
		case "--depth":
			i++
			if i < len(args) {
				fmt.Sscanf(args[i], "%d", &g.Depth)
			}
		case "--max-cores", "-m":
			i++
			if i < len(args) {
				fmt.Sscanf(args[i], "%d", &g.MaxCores)
			}
		case "--top", "-t":
			i++
			if i < len(args) {
				fmt.Sscanf(args[i], "%d", &g.Top)
			}
		case "--config-file":
			i++
			if i < len(args) {
				g.ConfigFile = args[i]
			}
		case "--db", "-D":
			i++
			if i < len(args) {
				g.DB = args[i]
			}
		case "--input-file", "-f":
			i++
			if i < len(args) {
				g.InputFile = args[i]
			}
		case "--output-file", "-o":
			i++
			if i < len(args) {
				g.OutputFile = args[i]
			}
		case "--log-file", "-l":
			i++
			if i < len(args) {
				g.LogFile = args[i]
			}
		case "--ignore-dirs", "-i":
			i++
			if i < len(args) {
				g.IgnoreDirs = parseStringList(args[i])
			}
		case "--ignore-dirs-pattern", "-I":
			i++
			if i < len(args) {
				g.IgnoreDirsPattern = parseStringList(args[i])
			}
		case "--ignore-from", "-X":
			i++
			if i < len(args) {
				g.IgnoreFrom = args[i]
			}
		case "--exclude-type", "-E":
			i++
			if i < len(args) {
				g.ExcludeType = parseStringList(args[i])
			}
		case "--type", "-T":
			i++
			if i < len(args) {
				g.Type = parseStringList(args[i])
			}
		case "--max-age":
			i++
			if i < len(args) {
				g.MaxAge = args[i]
			}
		case "--min-age":
			i++
			if i < len(args) {
				g.MinAge = args[i]
			}
		case "--since":
