package main

import (
	"fmt"
	"os"
	"os/exec"
	"strconv"
	"strings"
)

type Printer struct {
	gdu *Gdu
}

func NewPrinter(gdu *Gdu) *Printer {
	return &Printer{gdu: gdu}
}

func (p *Printer) Print(result *AnalysisResult) {
	if p.gdu.ShowDisks {
		p.printDisks()
		return
	}

	if p.gdu.Summarize {
		p.printSummary(result)
		return
	}

	if p.gdu.Depth > 0 {
		p.printWithDepth(result)
		return
	}

	p.printItems(result.Items)
}

func (p *Printer) printSummary(result *AnalysisResult) {
	if len(result.Items) > 0 {
		item := result.Items[0]
		fmt.Printf("%s %s\n", p.formatSize(item.Size), filepath.Base(item.Path))
	}
}

func (p *Printer) printItems(items []*FileInfo) {
	for _, item := range items {
		if !item.IsDir || len(item.Children) > 0 {
			p.printItem(item, "")
		}
	}
}

func (p *Printer) printItem(item *FileInfo, prefix string) {
	if item.IsDir && len(item.Children) > 0 {
		// Print directory
		fmt.Printf("%s %s\n", p.formatSize(item.Size), filepath.Base(item.Path))
	} else if !item.IsDir {
		// Print file
		fmt.Printf("%s %s\n", p.formatSize(item.Size), item.Name)
	}
}

func (p *Printer) printWithDepth(result *AnalysisResult) {
	if len(result.Items) == 0 {
		return
	}

	root := result.Items[0]
	p.printItemWithDepth(root, 0)
}

func (p *Printer) printItemWithDepth(item *FileInfo, currentDepth int) {
	if currentDepth > p.gdu.Depth {
		return
	}

	if item.IsDir {
		fmt.Printf("%s %s\n", p.formatSize(item.Size), item.Path)
	} else {
		fmt.Printf("%s %s\n", p.formatSize(item.Size), item.Path)
	}

	if currentDepth < p.gdu.Depth {
		for _, child := range item.Children {
			p.printItemWithDepth(child, currentDepth+1)
		}
	}
}

func (p *Printer) formatSize(bytes int64) string {
	sizeStr := ""

	if p.gdu.NoPrefix {
		return fmt.Sprintf("%d", bytes)
	}

	if p.gdu.SI {
		// SI units (kB, MB, GB - base 1000)
		if bytes < 1000 {
			sizeStr = fmt.Sprintf("%.0f B", float64(bytes))
		} else if bytes < 1000*1000 {
			sizeStr = fmt.Sprintf("%.1f kB", float64(bytes)/1000)
		} else if bytes < 1000*1000*1000 {
			sizeStr = fmt.Sprintf("%.1f MB", float64(bytes)/(1000*1000))
		} else if bytes < 1000*1000*1000*1000 {
			sizeStr = fmt.Sprintf("%.1f GB", float64(bytes)/(1000*1000*1000))
		} else {
			sizeStr = fmt.Sprintf("%.1f TB", float64(bytes)/(1000*1000*1000*1000))
		}
	} else {
		// Binary units (KiB, MiB, GiB - base 1024)
		if bytes < 1024 {
			sizeStr = fmt.Sprintf("%.0f B", float64(bytes))
		} else if bytes < 1024*1024 {
			sizeStr = fmt.Sprintf("%.1f KiB", float64(bytes)/1024)
		} else if bytes < 1024*1024*1024 {
			sizeStr = fmt.Sprintf("%.1f MiB", float64(bytes)/(1024*1024))
		} else if bytes < 1024*1024*1024*1024 {
			sizeStr = fmt.Sprintf("%.1f GiB", float64(bytes)/(1024*1024*1024))
		} else {
			sizeStr = fmt.Sprintf("%.1f TiB", float64(bytes)/(1024*1024*1024*1024))
		}
	}

	// Right-align to 10 characters
	return fmt.Sprintf("%10s", sizeStr)
}

func (p *Printer) printDisks() {
	// Get disk info using df
	cmd := exec.Command("df", "-P")
	output, err := cmd.Output()
	if err != nil {
		return
	}

	lines := strings.Split(string(output), "\n")
	printed := false

	for _, line := range lines {
		if line == "" {
			continue
		}

		parts := strings.Fields(line)
		if len(parts) < 6 {
			continue
		}

		if parts[0] == "Filesystem" {
			continue
		}

		device := parts[0]
		sizeStr := parts[1]
		usedStr := parts[2]
		availStr := parts[3]
		usePercent := parts[4]
		mountpoint := parts[5]

		// Parse numbers
		sizeKB := int64(0)
		usedKB := int64(0)
		availKB := int64(0)
		usePercentNum := 0

		fmt.Sscanf(sizeStr, "%d", &sizeKB)
		fmt.Sscanf(usedStr, "%d", &usedKB)
		fmt.Sscanf(availStr, "%d", &availKB)
		fmt.Sscanf(usePercent, "%d%%", &usePercentNum)

		// Convert KB to bytes
		size := sizeKB * 1024
		used := usedKB * 1024
		avail := availKB * 1024

		if !printed {
			fmt.Printf("%10s %10s %10s %10s %5s %s\n", "Device", "Size", "Used", "Free", "Used%", "Mount point")
			printed = true
		}

		fmt.Printf("%10s %10s %10s %10s %3d%% %s\n",
			device,
			p.formatSize(size),
			p.formatSize(used),
			p.formatSize(avail),
			usePercentNum,
			mountpoint)
	}
}

