	"path/filepath"
	"sort"
	"syscall"
	"time"
)

type FileInfo struct {
	Name         string
	Path         string
	Size         int64  // Disk usage (with block sizes)
	ApparentSize int64  // Actual file size
	IsDir        bool
	Children     []*FileInfo
	MTime        time.Time
	ItemCount    int
	DeviceID     uint64
}

type AnalysisResult struct {
	Items    []*FileInfo
	TotalSize int64
}

type Analyzer struct {
	gdu *Gdu
	ignoreDirs map[string]bool
	visitedInodes map[string]bool
}

func NewAnalyzer(gdu *Gdu) *Analyzer {
	a := &Analyzer{
		gdu: gdu,
		ignoreDirs: make(map[string]bool),
		visitedInodes: make(map[string]bool),
	}

	// Add default ignore dirs
	defaultIgnores := []string{"/proc", "/dev", "/sys", "/run"}
	for _, dir := range defaultIgnores {
		a.ignoreDirs[dir] = true
	}

	// Add user-provided ignore dirs
	for _, dir := range gdu.IgnoreDirs {
		a.ignoreDirs[dir] = true
	}

	return a
}

func (a *Analyzer) Analyze(scanDir string) (*AnalysisResult, error) {
	// Convert to absolute path
	absPath, err := filepath.Abs(scanDir)
	if err != nil {
		return nil, err
	}

	result := &AnalysisResult{
		Items: make([]*FileInfo, 0),
	}

	rootInfo, err := a.analyzeDir(absPath, 0)
	if err != nil {
		return nil, err
	}

	if rootInfo != nil {
		result.Items = append(result.Items, rootInfo)
		result.TotalSize = rootInfo.Size
	}

	return result, nil
}

func (a *Analyzer) analyzeDir(path string, depth int) (*FileInfo, error) {
	info := &FileInfo{
		Name:     filepath.Base(path),
		Path:     path,
		IsDir:    true,
		Children: make([]*FileInfo, 0),
	}

	// Get device ID for cross-filesystem checks
	stat, err := os.Stat(path)
	if err != nil {
		return nil, err
	}

	// Get device ID
	if sys, ok := stat.Sys().(*syscall.Stat_t); ok {
		info.DeviceID = uint64(sys.Dev)
	}

	// Check if should skip this directory
	if a.shouldIgnore(path) {
		return nil, nil
	}

	entries, err := os.ReadDir(path)
	if err != nil {
		return nil, nil
	}

	totalSize := int64(0)
	totalApparent := int64(0)
	itemCount := 0

	for _, entry := range entries {
		if a.gdu.NoHidden && entry.Name()[0:1] == "." {
			continue
		}

		entryPath := filepath.Join(path, entry.Name())
		entryInfo, err := entry.Info()
		if err != nil {
			continue
		}

		if entry.IsDir() {
			if a.shouldIgnore(entryPath) {
				continue
			}

			if a.gdu.NoCross {
				// Check device ID
				if sys, ok := entryInfo.Sys().(*syscall.Stat_t); ok {
					if uint64(sys.Dev) != info.DeviceID {
						continue
					}
				}
			}

			childInfo, err := a.analyzeDir(entryPath, depth+1)
			if err == nil && childInfo != nil {
				info.Children = append(info.Children, childInfo)
				totalSize += childInfo.Size
				totalApparent += childInfo.ApparentSize
				if childInfo.MTime.After(info.MTime) {
					info.MTime = childInfo.MTime
				}
				itemCount += 1 + childInfo.ItemCount
			}
		} else {
			size := entryInfo.Size()

			// For disk usage, round up to block size (4KB typical)
			blockSize := int64(4096)
			alignedSize := ((size + blockSize - 1) / blockSize) * blockSize

			totalSize += alignedSize
			totalApparent += size
			itemCount++

			if entryInfo.ModTime().After(info.MTime) {
				info.MTime = entryInfo.ModTime()
			}

			childInfo := &FileInfo{
				Name:         entry.Name(),
				Path:         entryPath,
				Size:         alignedSize,
				ApparentSize: size,
				IsDir:        false,
				MTime:        entryInfo.ModTime(),
			}
			info.Children = append(info.Children, childInfo)
		}
	}

	// Add directory size itself (one block)
	blockSize := int64(4096)
	dirSize := blockSize
	totalSize += dirSize

	info.Size = totalSize
	info.ApparentSize = totalApparent
	info.ItemCount = itemCount

	// Sort children by size
	sort.Slice(info.Children, func(i, j int) bool {
		return info.Children[i].Size > info.Children[j].Size
	})

	return info, nil
}

func (a *Analyzer) shouldIgnore(path string) bool {
	if ignored, ok := a.ignoreDirs[path]; ok && ignored {
		return true
	}

	// Check relative paths
	for ignorePath := range a.ignoreDirs {
		if filepath.HasPrefix(path, ignorePath) {
			return true
		}
	}

	return false
}
