cat > /workspace/cmd/gdu/printer.go << 'GOEOF'
package main

import (
	"fmt"
	"os/exec"
	"path/filepath"
	"strings"
)

type Printer struct {
	gdu *Gdu
}

func NewPrinter(gdu *Gdu) *Printer {
	return &Printer{gdu: gdu}
}

func (p *Printer) Print(result *AnalysisResult) {
	if p.gdu.ShowDisks {
		p.printDisks()
		return
	}

	if p.gdu.Summarize {
		p.printSummary(result)
		return
	}

	if p.gdu.Depth > 0 {
		p.printWithDepth(result)
		return
	}

	// Default: show only top-level children of root
	p.printTopLevel(result)
}

func (p *Printer) printSummary(result *AnalysisResult) {
	if len(result.Items) > 0 {
		item := result.Items[0]
		fmt.Printf("%s %s\n", p.formatSize(item), filepath.Base(item.Path))
	}
}

func (p *Printer) printTopLevel(result *AnalysisResult) {
	if len(result.Items) == 0 {
		return
	}

	root := result.Items[0]
	// Print children of root, sorted by size (already sorted in analyzer)
	for _, child := range root.Children {
		if child.IsDir {
			fmt.Printf("%s /%s\n", p.formatSize(child), child.Name)
		} else {
			fmt.Printf("%s %s\n", p.formatSize(child), child.Name)
		}
	}
}

func (p *Printer) printItems(items []*FileInfo) {
	for _, item := range items {
		if !item.IsDir || len(item.Children) > 0 {
			p.printItem(item, "")
		}
	}
}

func (p *Printer) printItem(item *FileInfo, prefix string) {
	if item.IsDir && len(item.Children) > 0 {
		// Print directory
		fmt.Printf("%s %s\n", p.formatSize(item), filepath.Base(item.Path))
		// Print children
		for _, child := range item.Children {
			p.printItem(child, "")
		}
	} else if !item.IsDir {
		// Print file
		fmt.Printf("%s %s\n", p.formatSize(item), item.Name)
	}
}

func (p *Printer) printWithDepth(result *AnalysisResult) {
	if len(result.Items) == 0 {
		return
	}

	root := result.Items[0]
	p.printItemWithDepth(root, 0)
}

func (p *Printer) printItemWithDepth(item *FileInfo, currentDepth int) {
	if currentDepth > p.gdu.Depth {
		return
	}

	if item.IsDir {
		fmt.Printf("%s %s\n", p.formatSize(item), item.Path)
	} else {
		fmt.Printf("%s %s\n", p.formatSize(item), item.Path)
	}

	if currentDepth < p.gdu.Depth {
		for _, child := range item.Children {
			p.printItemWithDepth(child, currentDepth+1)
		}
	}
}

func (p *Printer) formatSize(info *FileInfo) string {
	// Determine which size to use
	var bytes int64
	if p.gdu.ShowApparentSize {
		bytes = info.ApparentSize
	} else {
		bytes = info.Size
	}

	sizeStr := ""

	if p.gdu.NoPrefix {
		return fmt.Sprintf("%d", bytes)
	}

	if p.gdu.SI {
		// SI units (kB, MB, GB - base 1000)
		if bytes < 1000 {
			sizeStr = fmt.Sprintf("%.0f B", float64(bytes))
		} else if bytes < 1000*1000 {
			sizeStr = fmt.Sprintf("%.1f kB", float64(bytes)/1000)
		} else if bytes < 1000*1000*1000 {
			sizeStr = fmt.Sprintf("%.1f MB", float64(bytes)/(1000*1000))
		} else if bytes < 1000*1000*1000*1000 {
			sizeStr = fmt.Sprintf("%.1f GB", float64(bytes)/(1000*1000*1000))
		} else {
			sizeStr = fmt.Sprintf("%.1f TB", float64(bytes)/(1000*1000*1000*1000))
		}
	} else {
		// Binary units (KiB, MiB, GiB - base 1024)
		if bytes < 1024 {
